package com.swir.stream;

import android.app.Activity;
import android.app.AlertDialog;
import android.os.Handler;
import android.os.Looper;
import android.widget.*;
import android.view.View;
import android.content.Intent;
import android.net.Uri;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

/** Public discovery only; account entry remains in the separate secure provider form. */
final class SourceExplorerDialog {
    interface Listener {boolean active();void add(SourceCandidate candidate);void privateLink(String value);}
    private final Activity activity;private final SourceExplorer engine;private final SourceExplorerStore store;private final ExecutorService executor;private final Listener listener;private final Handler main=new Handler(Looper.getMainLooper());
    private final List<String> countryCodes,countryNames;private final Set<String> countries;private AtomicBoolean cancel=new AtomicBoolean();private AlertDialog page;private boolean closed,busy;private String query="",address="",message="";private int filter;private List<SourceCandidate> rows=new ArrayList<>();
    SourceExplorerDialog(Activity activity,SourceExplorer engine,SourceExplorerStore store,ExecutorService executor,Listener listener,Set<String> countries,List<String> codes,List<String> names){this.activity=activity;this.engine=engine;this.store=store;this.executor=executor;this.listener=listener;this.countries=new LinkedHashSet<>(countries);countryCodes=new ArrayList<>(codes);countryNames=new ArrayList<>(names);}
    void show(){closed=false;rows=store.load();if(store.unreadable())message="Zapis wyników jest uszkodzony. Plik zachowano; aby zacząć nowy zapis, wybierz Wyczyść wyniki.";render();}
    void showPortals(){query="free public Stalker Ministra portal";filter=3;message="Szukaj publicznych stron portali. Sam adres nie potwierdza darmowego dostępu. Dane własnego konta wpisujesz dopiero przy dodawaniu źródła.";show();}
    void close(){closed=true;cancel.set(true);dismiss();}
    private boolean active(){return !closed&&listener.active()&&!activity.isFinishing()&&!activity.isDestroyed();}
    private void dismiss(){if(page!=null){page.dismiss();page=null;}}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private LinearLayout column(){LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);return box;}
    private TextView text(String value,int size){TextView view=new TextView(activity);view.setText(value);view.setTextColor(0xffdce7f7);view.setTextSize(size);view.setPadding(0,dp(5),0,dp(5));return view;}
    private Button button(String value,String tag,Runnable action){Button view=new Button(activity);view.setText(value);view.setAllCaps(false);view.setTextSize(14);view.setMinHeight(dp(48));view.setTag(tag);view.setFocusable(true);view.setOnClickListener(v->action.run());return view;}
    private EditText input(String hint,String tag,String value){EditText field=new EditText(activity);field.setHint(hint);field.setText(value);field.setTextSize(15);field.setSingleLine(true);field.setSaveEnabled(false);field.setTag(tag);if(android.os.Build.VERSION.SDK_INT>=26)field.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);return field;}
    private void display(String title,LinearLayout box){dismiss();ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(true);scroll.addView(box);page=new AlertDialog.Builder(activity).setTitle(title).setView(scroll).setNegativeButton("Zamknij",(d,w)->close()).create();page.setOnCancelListener(d->close());page.show();if(page.getWindow()!=null){page.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xff101a2c));page.getWindow().setLayout(-1,-1);}}
    private void render(){if(!active())return;LinearLayout box=column();box.setTag("source_explorer");box.setPadding(dp(16),dp(6),dp(16),dp(10));box.addView(text("Publiczne strony, playlisty i transmisje. Adres portalu wymaga Twojego zarejestrowanego MAC. Wyniki nie oznaczają dostępu do kanałów.",13));
        EditText term=input("Kanał, nadawca lub temat","explorer_query",query);box.addView(term);Button areas=button(countryCaption(),"explorer_countries",()->countryPicker(term));box.addView(areas);
        box.addView(button(busy?"Wyszukiwanie trwa…":"Szukaj w WWW","explorer_search",()->{if(busy)return;query=term.getText().toString().trim();if(SourceExplorerRules.privateText(query)&&!SourceLinkParser.importCandidate(query)){query="";term.setText("");term.setError("Wpisz nazwę kanału lub temat, bez danych kont.");return;}if(SourceLinkParser.importCandidate(query)){String value=query;query="";term.setText("");close();listener.privateLink(value);return;}start(false,query);}));
        EditText url=input("Publiczna strona lub link do mediów","explorer_url",address);box.addView(url);box.addView(button("Analizuj podany adres","explorer_analyze",()->{if(busy)return;address=url.getText().toString().trim();try{SourceExplorerHttp.allowed(address);}catch(Exception error){url.setText("");address="";url.setError("Wklej publiczny adres bez danych kont. Własne konto dodaj przez Wklej link.");return;}query=term.getText().toString().trim();if(SourceExplorerRules.privateText(query)||SourceLinkParser.importCandidate(query)){query="";term.setText("");}start(true,address);}));
        if(busy)box.addView(button("Przerwij • zachowaj poprzednie wyniki","explorer_cancel",()->cancel.set(true)));
        if(!message.isEmpty())box.addView(text(message,13));
        Spinner types=new Spinner(activity);types.setTag("explorer_filter");types.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"Wszystkie wyniki","Playlisty URL","Bezpośrednie transmisje","Portale MAC","Strony / informacje"}));types.setSelection(filter);box.addView(types);LinearLayout cards=column();cards.setTag("explorer_results");box.addView(cards);fill(cards);types.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){filter=position;fill(cards);}});
        box.addView(button("Wyczyść zapisane wyniki tego profilu","explorer_clear",()->{if(busy)return;new AlertDialog.Builder(activity).setTitle("Wyczyścić wyniki eksploratora?").setMessage("Usunie tylko zapisane publiczne wyniki. Playlisty, konta, ulubione i historia pozostaną.").setPositiveButton("Wyczyść",(d,w)->{try{store.clear();rows=new ArrayList<>();message="Wyczyszczono wyniki.";render();}catch(Exception error){message=error.getMessage();render();}}).setNegativeButton("Anuluj",null).show();}));display("Eksplorator źródeł • by Swir",box);
    }
    private void fill(LinearLayout cards){cards.removeAllViews();int shown=0;for(SourceCandidate candidate:rows){int kind=candidate.kind==SourceExplorerRules.Kind.PublicPlaylist?1:candidate.kind==SourceExplorerRules.Kind.DirectStream?2:candidate.kind==SourceExplorerRules.Kind.PortalCandidate?3:4;if(filter!=0&&filter!=kind)continue;shown++;Button result=button(candidate.title+"\n"+label(candidate.kind)+" • "+host(candidate.url)+"\n"+candidate.status+"\n"+(candidate.checkedAt==0?"Jeszcze nie sprawdzono":date(candidate.checkedAt)),"explorer_result_"+candidate.id,()->details(candidate));result.setSingleLine(false);result.setMinHeight(dp(96));cards.addView(result);}if(shown==0)cards.addView(text("Brak wyników w tej sekcji. Uruchom wyszukiwanie albo przeanalizuj publiczny adres.",14));}
    void details(SourceCandidate candidate){if(!active())return;LinearLayout box=column();box.setTag("explorer_details");box.setPadding(dp(18),dp(8),dp(18),dp(12));box.addView(text(candidate.title,20));box.addView(text(label(candidate.kind)+"\n"+candidate.status+"\n\nAdres: "+candidate.url+"\nPochodzenie: "+candidate.evidenceUrl+"\nZnaleziono: "+date(candidate.discoveredAt)+"\nSprawdzono: "+(candidate.checkedAt==0?"jeszcze nie":date(candidate.checkedAt))+"\nData podana przez serwer: "+(candidate.modifiedAt==0?"brak":date(candidate.modifiedAt))+(candidate.channelCount>0?"\nAdresów na liście: "+candidate.channelCount:"")+"\n\nHTTP lub odczyt manifestu nie potwierdza obrazu ani dostępu. Odtwarzanie sprawdzi Swir Player po dodaniu źródła.",14));
        if(candidate.kind!=SourceExplorerRules.Kind.ProviderPage)box.addView(button(candidate.kind==SourceExplorerRules.Kind.PortalCandidate?"Dodaj portal • wpiszę własny MAC":candidate.kind==SourceExplorerRules.Kind.PublicPlaylist?"Dodaj do Playlist URL":candidate.protectedMedia?"Otwórz własną konfigurację DRM":"Dodaj transmisję do Playlist URL","explorer_add",()->{if(!active())return;close();listener.add(candidate);}));
        box.addView(button("Analizuj ponownie","explorer_recheck",()->{address=candidate.url;start(true,address);}));box.addView(button("Otwórz stronę w przeglądarce","explorer_website",()->{try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(candidate.url)));}catch(Exception ignored){Toast.makeText(activity,"Brak przeglądarki na urządzeniu.",Toast.LENGTH_LONG).show();}}));box.addView(button("Usuń wynik","explorer_remove",()->{if(busy)return;try{store.remove(candidate.id);rows=store.load();render();}catch(Exception error){message=error.getMessage();render();}}));box.addView(button("Wróć do wyników","explorer_back",this::render));display("Szczegóły publicznego źródła",box);
    }
    private void start(boolean analyze,String value){if(!active()||busy)return;busy=true;cancel=new AtomicBoolean();AtomicBoolean operation=cancel;message="Trwa ograniczone wyszukiwanie publicznych źródeł…";render();executor.execute(()->{try{SourceExplorer.Scan scan=analyze?engine.analyze(value,null,operation):engine.search(value,new LinkedHashSet<>(countries),null,operation);if(!active())operation.set(true);PublicHttp.checkCancelled(operation);List<SourceCandidate> merged=store.merge(scan.candidates,operation);main.post(()->{if(!active()||operation!=cancel)return;busy=false;rows=merged;message=scan.candidates.size()+" wyników • "+scan.pages+" stron • "+scan.failed+" błędów\n"+String.join("\n",scan.notes);render();});}catch(Exception error){main.post(()->{if(!active()||operation!=cancel)return;busy=false;message=operation.get()?"Przerwano. Poprzednie wyniki zachowano.":error.getMessage()==null?"Nie udało się sprawdzić źródeł. Poprzednie wyniki zachowano.":error.getMessage();render();});}});}
    private String countryCaption(){return "Kraje w zapytaniu: "+(countries.isEmpty()?"cały świat":String.join(", ",countries));}
    private void countryPicker(EditText term){if(busy)return;query=term.getText().toString();if(SourceExplorerRules.privateText(query)||SourceLinkParser.importCandidate(query)){query="";term.setText("");}boolean[] checked=new boolean[countryCodes.size()];for(int i=0;i<checked.length;i++)checked[i]=countries.contains(countryCodes.get(i));new AlertDialog.Builder(activity).setTitle("Kraje wyszukiwania").setMultiChoiceItems(countryNames.toArray(new String[0]),checked,(d,i,on)->checked[i]=on).setPositiveButton("Zastosuj",(d,w)->{Set<String> selected=new LinkedHashSet<>();for(int i=0;i<checked.length;i++)if(checked[i])selected.add(countryCodes.get(i));countries.clear();countries.addAll(selected);render();}).setNeutralButton("Cały świat",(d,w)->{countries.clear();render();}).setNegativeButton("Anuluj",null).show();}
    static String label(SourceExplorerRules.Kind kind){return kind==SourceExplorerRules.Kind.PortalCandidate?"Portal • potrzebny własny MAC":kind==SourceExplorerRules.Kind.PublicPlaylist?"Publiczna playlista":kind==SourceExplorerRules.Kind.DirectStream?"Bezpośrednia transmisja":"Strona / informacje";}
    private static String date(long at){return new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.getDefault()).format(new Date(at));}
    private static String host(String url){try{return new java.net.URI(url).getHost();}catch(Exception error){return "źródło";}}
}
